import sys
def solve(s):
 s=s.strip(); odd=sorted((c for c in s if int(c)%2),reverse=True); even=sorted((c for c in s if not int(c)%2),reverse=True); i=j=0; out=[]
 for c in s:
  if int(c)%2: out.append(odd[i]); i+=1
  else: out.append(even[j]); j+=1
 return "".join(out)
if __name__=="__main__": print(solve(sys.stdin.read()))

import sys
def solve(raw):
 z=raw.split(); n=int(z[0]); out=[]
 for w in z[1:1+n]:
  changes=0; last=None
  for c in w:
   if c==last: changes+=1; last=None
   else: last=c
  out.append(str(changes))
 return " ".join(out)
if __name__=="__main__": print(solve(sys.stdin.read()))
